import{_ as d,a0 as r,w as u,s as p,ao as a,I as s,x as t,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const B=JSON.parse('{"title":"Linux 有问必答：如何在 Linux 中永久修改 USB 设备权限 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有问必答：如何在 Linux 中永久修改 USB 设备权限 | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有问必答：如何在 Linux 中永久修改 USB 设备权限 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有问必答：如何在 Linux 中永久修改 USB 设备权限 | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20151012 Linux FAQs with Answers--How to change USB device permission permanently on Linux","title":"Linux 有问必答：如何在 Linux 中永久修改 USB 设备权限","tag":"201510","desc":""},"relativePath":"201510/20151012 Linux FAQs with Answers--How to change USB device permission permanently on Linux.md","filePath":"[post].md"}'),l={name:"201510/20151012 Linux FAQs with Answers--How to change USB device permission permanently on Linux.md"};function m(x,e,c,g,S,f){const o=r("Link");return u(),p("div",null,[e[13]||(e[13]=a(`<h1 id="linux-有问必答-如何在-linux-中永久修改-usb-设备权限" tabindex="-1">Linux 有问必答：如何在 Linux 中永久修改 USB 设备权限 <a class="header-anchor" href="#linux-有问必答-如何在-linux-中永久修改-usb-设备权限" aria-label="Permalink to “Linux 有问必答：如何在 Linux 中永久修改 USB 设备权限”">​</a></h1><blockquote><p><strong>提问</strong>：当我尝试在 Linux 中运行 USB GPS 接收器时我遇到了下面来自 gpsd 的错误。</p><pre><code>gpsd[377]: gpsd:ERROR: read-only device open failed: Permission denied
gpsd[377]: gpsd:ERROR: /dev/ttyUSB0: device activation failed.
gpsd[377]: gpsd:ERROR: device open failed: Permission denied - retrying read-only 
</code></pre><p>看上去 gpsd 没有权限访问 USB 设备（/dev/ttyUSB0）。我该如何永久修改它在Linux上的权限？</p></blockquote><p>当你在运行一个会读取或者写入USB设备的进程时，进程的用户/组必须有权限这么做才行。当然你可以手动用<code>chmod</code>命令改变 USB 设备的权限，但是手动的权限改变只是暂时的。USB 设备会在下次重启时恢复它的默认权限。</p><p><img src="https://farm6.staticflickr.com/5741/20848677843_202ff53303_c.jpg" alt=""></p><p>作为一个永久的方式，你可以创建一个基于 udev 的 USB 权限规则，它可以根据你的选择分配任何权限模式。下面是该如何做。</p><p>首先，你需要找出 USB 设备的 vendorID 和 productID。使用<code>lsusb</code>命令。</p><pre><code>$ lsusb -vvv 
</code></pre><p><img src="https://farm1.staticflickr.com/731/20848677743_39f76eb403_c.jpg" alt=""></p><p>上面<code>lsusb</code>的输出中，找出你的 USB 设备，并找出&quot;idVendor&quot;和&quot;idProduct&quot;字段。本例中,我们的结果是<code>idVendor (0x067b)</code>和 <code>idProduct (0x2303)</code></p><p>下面创建一个新的udev规则。</p><pre><code>$ sudo vi /etc/udev/rules.d/50-myusb.rules 
</code></pre><hr><pre><code>SUBSYSTEMS==&quot;usb&quot;, ATTRS{idVendor}==&quot;067b&quot;, ATTRS{idProduct}==&quot;2303&quot;, GROUP=&quot;users&quot;, MODE=&quot;0666&quot;
</code></pre><p>用你自己的&quot;idVendor&quot;和&quot;idProduct&quot;来替换。<strong>MODE=&quot;0666&quot;</strong>表示USB设备的权限。</p><p>现在重启电脑并重新加载 udev 规则：</p><pre><code>$ sudo udevadm control --reload 
</code></pre><p>接着验证下 USB 设备的权限。</p><p><img src="https://farm1.staticflickr.com/744/21282872179_9a4a05d768_b.jpg" alt=""></p><hr>`,19)),s("p",null,[e[1]||(e[1]=t("via: ",-1)),n(o,{href:"http://ask.xmodulo.com/change-usb-device-permission-linux.html"},{default:i(()=>[...e[0]||(e[0]=[t("http://ask.xmodulo.com/change-usb-device-permission-linux.html",-1)])]),_:1})]),s("p",null,[e[5]||(e[5]=t("作者：",-1)),n(o,{href:"http://ask.xmodulo.com/author/nanni"},{default:i(()=>[...e[2]||(e[2]=[t("Dan Nanni",-1)])]),_:1}),e[6]||(e[6]=t(" 译者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:i(()=>[...e[3]||(e[3]=[t("geekpi",-1)])]),_:1}),e[7]||(e[7]=t(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[10]||(e[10]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原创编译，",-1)),n(o,{href:"https://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[t("Linux中国",-1)])]),_:1}),e[12]||(e[12]=t(" 荣誉推出",-1))])])}const v=d(l,[["render",m]]);export{B as __pageData,v as default};
